function passkeyCandidate(baseline=false):Extract<Candidate,{family:'Passkey'}>{const value=candidate('Passkey',baseline);if(value.family!=='Passkey')throw new Error('Wrong synthetic Passkey family');return value;}
function passkeyFields(value:ReturnType<typeof passkeyCandidate>):Record<string,string>{
 const m=value.value.metadata,v=value.value.values,fields:Record<string,string>={'metadata.version':m.versionId,'metadata.status':m.status,'metadata.supersedes':m.supersedesVersionId??'—','metadata.scope':m.scope,'evidence.0':m.approvalEvidenceReferences[0]!,'interval.from':m.effectiveInterval.from,'interval.includesFrom':String(m.effectiveInterval.includesFrom),'interval.until':m.effectiveInterval.until??'—','interval.includesUntil':String(m.effectiveInterval.includesUntil)};
 for(const [key,item] of Object.entries(v))if(key!=='allowedAlgorithms'&&key!=='assuranceMappings')fields['values.'+key]=String(item);v.allowedAlgorithms.forEach((item,index)=>{fields['algorithm.'+index]=String(item);});for(const [key,item] of Object.entries(v.assuranceMappings))fields['method.'+key]=item;return fields;
}
