function factorFields(value:ReturnType<typeof factorCandidate>):Record<string,string>{const fields:Record<string,string>={};for(const [key,item] of Object.entries(value.value))if(key!=='effectiveInterval')fields[key]=String(item);const i=value.value.effectiveInterval;return {...fields,'interval.from':i.from,'interval.includesFrom':String(i.includesFrom),'interval.until':i.until??'—','interval.includesUntil':String(i.includesUntil)};}
