test('RecoveryCodes canonical routes guard direct entry reload history and capabilities',async({page})=>{
 test.setTimeout(90_000);const server=await fixture(page,{denyPublish:true}),family='RecoveryCodes' as const;for(const view of ['edit','review','history'] as const){const path=configurationPath(family,view),before=server.guards;await page.goto(path+'?candidate=discard#discard');await expect(page).toHaveURL('http://127.0.0.1:5298'+path);await expect.poll(()=>server.guards).toBeGreaterThan(before);await expect(page.locator('[data-tunner-screen="A-ID-SETTINGS-'+family+'-'+view+'"]')).toBeVisible();await page.getByLabel('Exact scope',{exact:true}).selectOption(scopeKey(scopes[family]));if(view!=='history'){await page.getByLabel('Saved candidate',{exact:true}).selectOption(proposalId);if(view==='edit')await expect(page.getByRole('button',{name:'Save draft',exact:true})).toBeEnabled();else await expect(page.getByRole('button',{name:'Publish configuration',exact:true})).toBeDisabled();}else await expect(page.locator('.configuration-history')).toHaveCount(1);const beforeReload=server.guards;await page.reload();await expect.poll(()=>server.guards).toBeGreaterThan(beforeReload);await expect(page.getByLabel('Exact scope',{exact:true})).toHaveValue('');await expect(page.locator('.configuration-diff')).toHaveCount(0);const alternate=view==='edit'?'review':'edit';await page.getByRole('link',{name:labels[alternate],exact:true}).click();await expect(page).toHaveURL('http://127.0.0.1:5298'+configurationPath(family,alternate));const beforeBack=server.guards;await page.goBack();await expect(page).toHaveURL('http://127.0.0.1:5298'+path);await expect.poll(()=>server.guards).toBeGreaterThan(beforeBack);await expect(page.getByLabel('Exact scope',{exact:true})).toHaveValue('');const beforeForward=server.guards;await page.goForward();await expect(page).toHaveURL('http://127.0.0.1:5298'+configurationPath(family,alternate));await expect.poll(()=>server.guards).toBeGreaterThan(beforeForward);await expect(page.getByLabel('Exact scope',{exact:true})).toHaveValue('');}expect(server.writes).toHaveLength(0);expect(await page.evaluate(()=>[localStorage.length,sessionStorage.length])).toEqual([0,0]);
});
test('RecoveryCodes laptop tablet and narrow form preserves exact work text keyboard correction and reflow',async({page},info)=>{
 test.setTimeout(120_000);const server=await fixture(page);for(const viewport of [{width:1024,height:768},{width:768,height:1024},{width:320,height:800}]){await page.setViewportSize(viewport);await select(page,'RecoveryCodes');const field=page.locator('[name="crypto.maximumHashWork"]');await expect(field).toHaveValue('9007199254740995');await field.fill('');await field.press('Tab');await expect(field).toHaveAttribute('aria-invalid','true');await page.getByRole('button',{name:'Save draft',exact:true}).focus();await page.keyboard.press('Enter');await expect(field).toBeFocused();await expect(page.getByRole('alert')).toContainText(labels.validationSummary);expect(server.writes).toHaveLength(0);await field.fill('9223372036854775807');await field.press('Tab');await expect(field).not.toHaveAttribute('aria-invalid','true');await expect(field).toHaveValue('9223372036854775807');await expect(page.getByRole('alert')).toHaveCount(0);expect(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth)).toBe(true);expect(await page.locator('input:visible,select:visible,button:visible').evaluateAll(items=>items.every(item=>{const b=item.getBoundingClientRect();return b.width>0&&b.left>=-0.5&&b.right<=innerWidth+0.5;}))).toBe(true);expect((await new AxeBuilder({page}).analyze()).violations).toEqual([]);if(viewport.width!==1024)await page.screenshot({path:info.outputPath(`recovery-codes-edit-${viewport.width}.png`),fullPage:true});}expect(server.writes).toHaveLength(0);
});
